def self.import_text(document, page_number, text)
    page = document.pages.find_by_page_number(page_number)
    page.update_attribute(:text, text) if page
  end

  def self.delete_for_document(document)
    where(:document_id => document.id).delete_all
  end

  def self.text_for_document(document)
    pages = where(:document_id => document.id).order(:page_number).pluck(:text)
    pages.join('')
  end

  def self.plain_text_for_document(document)
    pages = where(:document_id => document.id).order(:page_number).pluck(:text)
    pages.map {|text| strip_tags(text) }.join('')
  end

  def self.words_for_document(document)
    plain_text_for_document(document).split(/\s+/).size
  end

  def self.update_page_text(page_id, text)
    where(:id => page_id).update_all(:text => text)
  end

  def self.reindex_all
    find_each { |page| page.solr_index }
  end

  def self.reindex_for_document(document)
    where(:document_id => document.id).find_each

